function amortizationSchedule(totalCost, months) {
  const monthlyAmount = totalCost / months;
  const schedule = [];
  let cumulative = 0;
  for (let month = 1; month <= months; month++) {
    cumulative += monthlyAmount;
    schedule.push({ month, amount: monthlyAmount, cumulative, remaining: totalCost - cumulative });
  }
  return schedule;
}

